    fn metadata_call(
        memory: &mut GuestMemory,
        state: &mut LoadedStaticElf,
        capture: Option<&mut CapturedOutput>,
        number: libc::c_long,
        args: [u64; 6],
    ) -> i64 {
        if let Some(output) = capture {
