    InitialExecCompleted,
    Lifecycle,
    Instruction,
    ThreadEntrySignal,
    SignalBoundary(CompletedSyscallBoundary),
    FaultBoundary(Box<PageZeroFault>),
    SyscallBoundary(CompletedSyscallBoundary),
